create type public.user_role as enum ('free','subscriber','expert','admin');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, username text unique, display_name text, role public.user_role not null default 'free', avatar_url text, bio text, venmo_handle text, cashapp_handle text, created_at timestamptz default now());
create table public.follows (follower_id uuid references public.profiles(id) on delete cascade, following_id uuid references public.profiles(id) on delete cascade, created_at timestamptz default now(), primary key(follower_id,following_id));
create table public.rankings (id bigint generated by default as identity primary key, author_id uuid references public.profiles(id) on delete cascade, season int not null default 2026, week int, scope text not null check(scope in ('weekly','overall','ros')), scoring text not null default 'ppr', position text not null default 'ALL', player_id text not null, rank int not null, note text, published boolean default false, updated_at timestamptz default now(), unique(author_id,season,week,scope,scoring,position,player_id));
create table public.posts (id bigint generated by default as identity primary key, author_id uuid references public.profiles(id) on delete cascade, body text not null, player_id text, post_type text default 'post', created_at timestamptz default now());
create table public.comments (id bigint generated by default as identity primary key, post_id bigint references public.posts(id) on delete cascade, author_id uuid references public.profiles(id) on delete cascade, body text not null, created_at timestamptz default now());
create table public.likes (post_id bigint references public.posts(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, primary key(post_id,user_id));
create table public.leagues (id uuid primary key default gen_random_uuid(), owner_id uuid references public.profiles(id), name text not null, provider text, external_id text, scoring jsonb default '{}'::jsonb, created_at timestamptz default now());
create table public.league_members (league_id uuid references public.leagues(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, team_name text, roster jsonb default '[]'::jsonb, primary key(league_id,user_id));
create table public.advice_threads (id uuid primary key default gen_random_uuid(), requester_id uuid references public.profiles(id), expert_id uuid references public.profiles(id), subject text, body text not null, status text default 'open', payment_status text default 'not_required', created_at timestamptz default now());
create table public.advice_messages (id bigint generated by default as identity primary key, thread_id uuid references public.advice_threads(id) on delete cascade, sender_id uuid references public.profiles(id), body text not null, created_at timestamptz default now());
create table public.expert_weekly_picks (id bigint generated by default as identity primary key, expert_id uuid references public.profiles(id), season int default 2026, week int not null, category text not null, player_id text not null, rank int, note text, published boolean default false, unique(expert_id,season,week,category,player_id));
create table public.pickem_picks (id bigint generated by default as identity primary key, user_id uuid references public.profiles(id), season int default 2026, week int not null, game_id text not null, team_abbr text not null, shared boolean default false, unique(user_id,season,week,game_id));

alter table public.profiles enable row level security; alter table public.follows enable row level security; alter table public.rankings enable row level security; alter table public.posts enable row level security; alter table public.comments enable row level security; alter table public.likes enable row level security; alter table public.leagues enable row level security; alter table public.league_members enable row level security; alter table public.advice_threads enable row level security; alter table public.advice_messages enable row level security; alter table public.expert_weekly_picks enable row level security; alter table public.pickem_picks enable row level security;
create policy "profiles public read" on public.profiles for select using(true); create policy "profile own update" on public.profiles for update using(auth.uid()=id);
create policy "rankings published read" on public.rankings for select using(published or auth.uid()=author_id); create policy "ranking owner write" on public.rankings for all using(auth.uid()=author_id) with check(auth.uid()=author_id);
create policy "posts public read" on public.posts for select using(true); create policy "posts own write" on public.posts for all using(auth.uid()=author_id) with check(auth.uid()=author_id);
create policy "comments public read" on public.comments for select using(true); create policy "comments own write" on public.comments for all using(auth.uid()=author_id) with check(auth.uid()=author_id);
create policy "likes public read" on public.likes for select using(true); create policy "likes own write" on public.likes for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "follows public read" on public.follows for select using(true); create policy "follows own write" on public.follows for all using(auth.uid()=follower_id) with check(auth.uid()=follower_id);
create policy "league member read" on public.leagues for select using(owner_id=auth.uid() or exists(select 1 from public.league_members lm where lm.league_id=id and lm.user_id=auth.uid())); create policy "league owner write" on public.leagues for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "league membership read" on public.league_members for select using(user_id=auth.uid() or exists(select 1 from public.leagues l where l.id=league_id and l.owner_id=auth.uid()));
create policy "advice participants" on public.advice_threads for select using(requester_id=auth.uid() or expert_id=auth.uid()); create policy "advice requester create" on public.advice_threads for insert with check(requester_id=auth.uid());
create policy "messages participants" on public.advice_messages for select using(exists(select 1 from public.advice_threads t where t.id=thread_id and (t.requester_id=auth.uid() or t.expert_id=auth.uid()))); create policy "messages participant insert" on public.advice_messages for insert with check(sender_id=auth.uid() and exists(select 1 from public.advice_threads t where t.id=thread_id and (t.requester_id=auth.uid() or t.expert_id=auth.uid())));
create policy "expert picks published" on public.expert_weekly_picks for select using(published or expert_id=auth.uid()); create policy "expert picks own" on public.expert_weekly_picks for all using(expert_id=auth.uid()) with check(expert_id=auth.uid());
create policy "pickem public shared" on public.pickem_picks for select using(shared or user_id=auth.uid()); create policy "pickem own" on public.pickem_picks for all using(user_id=auth.uid()) with check(user_id=auth.uid());

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,username,display_name) values(new.id, split_part(new.email,'@',1), split_part(new.email,'@',1)); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
